// Dev Server: runs npm in a project folder on your computer.
// Your project folders and computer type are kept on the phone (cb.storage).

const ADD = '+ Add a project';

async function projects() {
  return (await cb.storage.get('projects')) || [];
}

// The project to use: the one picked last, the only one, or ask.
async function current() {
  const list = await projects();
  const chosen = await cb.storage.get('current');
  if (chosen && list.includes(chosen)) return chosen;
  if (list.length === 1) return list[0];
  return pickProject();
}

async function addProject() {
  const answer = await cb.ask('Project folder on your computer', { placeholder: '~/code/my-app' });
  const dir = (answer || '').trim();
  if (!dir) return null;
  const list = await projects();
  if (!list.includes(dir)) list.push(dir);
  await cb.storage.set('projects', list);
  await cb.storage.set('current', dir);
  return dir;
}

async function pickProject() {
  const list = await projects();
  if (list.length === 0) return addProject();
  const choice = await cb.choose('Which project?', [...list, ADD]);
  if (choice === null) return null;
  if (choice === ADD) return addProject();
  await cb.storage.set('current', choice);
  return choice;
}

async function project() {
  const dir = await pickProject();
  return dir ? 'Project: ' + dir : null;
}

async function forgetProject() {
  const list = await projects();
  if (list.length === 0) return 'No projects saved.';
  const dir = await cb.choose('Forget which project?', list);
  if (dir === null) return null;
  if (!(await cb.confirm('Forget ' + dir + '? Nothing on your computer changes.'))) return null;
  await cb.storage.set('projects', list.filter((p) => p !== dir));
  if ((await cb.storage.get('current')) === dir) await cb.storage.remove('current');
  return 'Forgot ' + dir;
}

async function computer() {
  let os = await cb.storage.get('os');
  if (!os) {
    os = await cb.choose('What does your computer run?', ['macOS', 'Windows', 'Linux']);
    if (os) await cb.storage.set('os', os);
  }
  return os;
}

async function openTerminal() {
  const os = await computer();
  if (os === 'macOS') {
    await cb.keys('cmd+space');
    await cb.wait(500);
    await cb.type('Terminal');
    await cb.wait(300);
    await cb.keys('return');
  } else if (os === 'Windows') {
    await cb.keys('win+r');
    await cb.wait(500);
    await cb.type('cmd');
    await cb.keys('return');
  } else if (os === 'Linux') {
    await cb.keys('ctrl+alt+t');
  } else {
    return null;
  }
  await cb.wait(1200);
  return 'Opened a terminal';
}

// Quotes a folder for the shell; a leading ~/ stays outside the quotes so it expands.
function quote(dir) {
  if (dir.startsWith('~/')) return '~/' + JSON.stringify(dir.slice(2));
  return JSON.stringify(dir);
}

// Types "cd <project> && npm <command>" into the focused terminal.
async function npm(command) {
  const dir = await current();
  if (!dir) return null;
  await cb.type('cd ' + quote(dir) + ' && npm ' + command);
  await cb.keys('return');
  return 'npm ' + command + ' · ' + dir;
}

async function runAsk() {
  const last = (await cb.storage.get('lastScript')) || 'test';
  const answer = await cb.ask('npm run …', { initial: last, placeholder: 'test' });
  const name = (answer || '').trim();
  if (!name) return null;
  await cb.storage.set('lastScript', name);
  return npm('run ' + name);
}

async function stop() {
  await cb.keys('ctrl+c');
  return 'Sent Ctrl-C';
}
